// from the symbols' own path data (960-unit grid, drawn 24dp). mi. apps use only Material Symbols Rounded.
// Regenerate by listing the names used and fetching each symbol's "materialsymbolsrounded/<name>_24px.svg".
package com.jlees.mibudget.ui.common

