private fun sym(name: String, path: String, mirror: Boolean = false): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 960f, 960f, autoMirror = mirror)
        .addGroup(translationY = 960f)
        .addPath(addPathNodes(path), fill = SolidColor(androidx.compose.ui.graphics.Color.Black))
        .clearGroup()
        .build()

